(()=>{const r={"id": "CONTENT-REDEMPTION-AMOUNT", "element_ids": ["pilot-serf:redemption-term", "pilot-serf:redemption-benefits"], "action": "replace_misleading_sentence", "reason": "Пересказ повторяет размерностную ошибку источника: полная выкупная сумма сравнивается с ежегодным оброком.", "source_ids": ["redemption_law", "redemption_esbe"], "new_text": "Сравнивать с годовым оброком следует ежегодный выкупной платёж, а не всю капитальную сумму. В обычной схеме ссуды в 80% капитализированного оброка ежегодные 6% от этой ссуды давали 80% прежнего годового оброка. Это расчёт по указанной схеме, а не утверждение об одинаковых условиях каждой сделки. Исходное выражение учебника «выкупная сумма» сохранено только в цитате.", "integration_note": "Первичные статьи повторно сверены; готово к интеграции. Заменить ошибочную авторскую фразу; цитату учебника сохранить. Дополнительные условия статьи 67 не превращать в общую 80%-схему."},sources={"1881_decree": {"title": "Указ 28 декабря 1881 года о выкупе наделов", "url": "https://istmat.org/node/33360", "locator": "ПСЗ, собрание III, том 1, № 575, пункт 1", "quote": "перевести на выкуп и причислить к разряду крестьян-собственников с 1 января 1883 года.", "verified": "Текст пункта 1 прочитан; территориальная оговорка сохранена."}, "russia134": {"title": "История России. 1825–1914 гг. 9 класс. В. Р. Мединский, А. В. Торкунов, 2026", "url": "https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view", "local_path": "/workspace/scratch/da605f6ebbe1/full-index-v21/work/textbooks/ba2deb75-e910-588c-a141-a1d5d01792c0/original.pdf", "file_id": "ba2deb75-e910-588c-a141-a1d5d01792c0", "pdf_page": 134, "printed_page": 134, "quote": "до истечения периода их временнообязанного состояния (а он растянулся на несколько десятилетий и завершился лишь в 1883 г.).", "verified": "Визуальная сверка с PDF."}, "austria132": {"title": "Всеобщая история. История Нового времени. XIX — начало XX в. 9 класс. § 11", "url": "https://drive.google.com/file/d/1RuUP3xZAiVq3OTL_UZE33_7_4EkDEZVB/view", "file_id": "f5afdcea-6c0a-5394-8507-ff97a165f5c1", "local_path": "/workspace/scratch/da605f6ebbe1/full-index-v21/work/textbooks/f5afdcea-6c0a-5394-8507-ff97a165f5c1/original.pdf", "pdf_page": 132, "printed_page": 132, "quote": "В августе 1848 г. парламент разработал компромиссный закон: земля выкупалась по рыночной стоимости, но сам крестьянин выплачивал лишь треть, другую треть — государство, а от выплаты оставшейся трети помещик по закону отказывался.", "verified": "Визуальная сверка с PDF. Формулировку о рыночной стоимости не переносить в авторский пересказ без уточнения официального источника."}, "austria131": {"title": "Всеобщая история. 9 класс. § 11", "url": "https://drive.google.com/file/d/1RuUP3xZAiVq3OTL_UZE33_7_4EkDEZVB/view", "file_id": "f5afdcea-6c0a-5394-8507-ff97a165f5c1", "pdf_page": 131, "printed_page": 131, "quote": "В немецких провинциях крестьяне пользовались личной свободой и платили оброк, в восточных провинциях сохранялись личная зависимость и барщина.", "verified": "Визуальная сверка с PDF."}, "austria_parliament": {"title": "Парламент Австрии: Reichstag 1848, Grundentlastung", "url": "https://www.parlament.gv.at/aktuelles/pk/jahr_2008/pk0740", "locator": "Разделы Dramatische Abstimmungen, Die Grundentlastung; публикация 09.09.2008", "support": "Личные повинности отменены без компенсации; часть иных земельных прав — с компенсацией. Основой служит капитализированная сумма повинностей; треть списана, треть уплачивает крестьянин, треть государство. Закон объявлен 7 сентября 1848 года.", "caution": "На странице есть опечатка 1848 в дате исполнительного патента Франца Иосифа; эту дату в материал не переносить."}, "cultivators1803": {"title": "Указ об отпуске помещиками своих крестьян на волю, 20 февраля 1803", "url": "https://constitution.garant.ru/history/act1600-1918/3050/", "locator": "Пункты 1, 3, 4; Российское законодательство X–XX вв., т.6, 1988", "quote": "Крестьяне и селения, от помещиков по таковым условиям с землею отпускаемые", "support": "Помещик добровольно освобождал крестьян с землёй по взаимно согласованным и утверждённым условиям; невыполнение крестьянами обязательств влекло предусмотренное указом возвращение."}, "konstantin": {"title": "Президентская библиотека: Главный комитет по крестьянскому делу", "url": "https://www.prlib.ru/history/618949", "support": "Источник уже проверен в V17: 1858 преобразование, 25 сентября (7 октября) 1860 председательство Константина."}, "redemption_law": {"title": "Положение о выкупе 19 февраля 1861 года", "url": "https://nnov.hse.ru/ba/law/igpr/vikkrep", "locator": "Статьи 65–67, 113–114", "support": "Годовой оброк капитализировался из 6%; ссуда обычно 80% при полном наделе или 75% при уменьшенном. Годовой выкупной платёж — 6% ссуды.", "verification": "Сверено непосредственно по полному HTML публикации НИУ ВШЭ: статьи 65, 66, 67, 113, 114 прочитаны. Загрузка оригинала выполнена без преобразования.", "local_path": "/workspace/scratch/49024123afc8/visual_audit/full-audit/vikkrep.html", "sha256": "3f12010a069712635fdb56ac8bbbc6ae0e174ac386329be9a4c942398714bf2f", "checked_passages": ["65 — основа: денежный оброк по уставной грамоте; корректировка при неполном наделе.", "66 — годовой оброк капитализируется из 6%; ссуда 80% при полном наделе, 75% при уменьшенном.", "67 — специальный случай полной ссуды при прежнем оброке ниже установленного местным положением; не универсальные 80%.", "113 — ежегодный платёж в казну: 6 копеек с рубля выкупной ссуды.", "114 — погашение 49 лет со дня выдачи ссуды."]}, "redemption_esbe": {"title": "ЭСБЕ: Выкупная операция", "url": "https://ru.wikisource.org/wiki/ЭСБЕ/Выкупная_операция", "support": "Прямо различаются капитализированная оценка, 80%/75% ссуды и ежегодные 6%; ежегодные платежи меньше оброка, полная выкупная сумма не равна ежегодному платежу."}};for(const id of r.element_ids){const l=window.CARD_LEARNING[id];const fix=t=>t.replace('Учебник сопоставляет выкупную сумму с оброком: она была почти на 20% меньше, а срок выплаты долга ограничивался 49 годами; оброк описан как бессрочная обязанность.','В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя.').replace('а выкупная сумма была почти на 20% меньше суммы оброка.','а ежегодный выкупной платёж в обычной схеме ссуды в 80% был на 20% меньше прежнего годового оброка; это не сравнение всей выкупной суммы с годовым платежом.');l.paragraphs=l.paragraphs?.map(fix);l.sections=l.sections?.map(s=>({...s,text:fix(s.text)}));l.sections.push({heading:'Основание расчёта и исключения',text:r.new_text+' Статья 66 предусматривала также ссуду в 75% при уменьшенном наделе, а статья 67 — особые случаи полной ссуды; поэтому расчёт не универсален.'});for(const k of r.source_ids){const v=sources[k];if(v&&!l.supplementalSources?.some(s=>s.url===v.url)){l.supplementalSources=l.supplementalSources||[];l.supplementalSources.push({title:v.title,url:v.url});}}}})();

